/**
 * build-ccc-reactor.js — Deploy CCC carbon credit reactor (V2 w/ custom burn address)
 * Burns to 0xA7BA1Ad556C99f44063Cee92A376c3fC5F3f1e65 (carbon credit retirement NFT)
 * Pairs: DDD, EGP, OGC, IGS, BTN, LGP, DHG, PKT (all 8 nations)
 * Run: node build-ccc-reactor.js
 */
const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '.env') });
const ethers = require('ethers');

const RPC = process.env.POLYGON_RPC;
const PK  = process.env.BALANCER_PRIVATE_KEY;
const p = new ethers.JsonRpcProvider(RPC);
const wallet = new ethers.Wallet(PK, p);

const NATION = '0x11f98a36acbd04ca3aa3a149d402affbd5966fe7';
const NATION_DEC = 16;
const NATION_USD = 0.10;
const NATION_NAME = 'CCC';

const NPM = '0xC36442b4a4522E871399CD717aBDD847Ab11FE88';
const ROUTER = '0x68b3465833fb72A70ecDF485E0e4C7bD8665Fc45';
const V3_FACTORY = '0x1F98431c8aD98523631AE4a59f267346ea31F984';
const FEE = 10000;
const TICK_LOW = -887200;
const TICK_HIGH = 887200;

const BURN_ADDRESS = '0xA7BA1Ad556C99f44063Cee92A376c3fC5F3f1e65'; // carbon credit retirement NFT

const PAIRS = [
  { name: 'DDD',  addr: '0x4bf82cf0d6b2afc87367052b793097153c859d38', dec: 18, usd: 0.00047221 },
  { name: 'EGP',  addr: '0x64f6f111e9fdb753877f17f399b759de97379170', dec: 18, usd: 0.00018123 },
    { name: 'OGC',  addr: '0xccf37622e6b72352e7b410481dd4913563038b7c', dec: 18, usd: 0.00025822 },
  { name: 'IGS',  addr: '0xe302672798d12e7f68c783db2c2d5e6b48ccf3ce', dec: 8,  usd: 0.00018373 },
  { name: 'BTN',  addr: '0xd7c584d40216576f1d8651eab8bef9de69497666', dec: 8,  usd: 0.00017708 },
  { name: 'LGP',  addr: '0xddc330761761751e005333208889bfe36c6e6760', dec: 18, usd: 0.00017478 },
  { name: 'DHG',  addr: '0x75c0a194cd8b4f01d5ed58be5b7c5b61a9c69d0a', dec: 8,  usd: 0.00017671 },
  { name: 'PKT',  addr: '0x8a088dceecbcf457762eb7c66f78fff27dc0c04a', dec: 18, usd: 0.00025383 },
];

const DEPLOY_ABI = [
  {"inputs":[{"internalType":"address","name":"_nationToken","type":"address"},{"internalType":"address","name":"_pm","type":"address"},{"internalType":"address","name":"_router","type":"address"},{"internalType":"address","name":"_burnAddress","type":"address"}],"stateMutability":"nonpayable","type":"constructor"},
  {"inputs":[],"name":"poolCount","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},
  {"inputs":[],"name":"nationToken","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},
  {"inputs":[],"name":"admin","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},
  {"inputs":[],"name":"burnAddress","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},
];

const BYTECODE = "";

const ERC20_ABI = [
  'function balanceOf(address) view returns (uint256)',
  'function approve(address,uint256) returns (bool)',
  'function allowance(address,address) view returns (uint256)',
];
const NPM_ABI = [
  'function mint((address token0,address token1,uint24 fee,int24 tickLower,int24 tickUpper,uint256 amount0Desired,uint256 amount1Desired,uint256 amount0Min,uint256 amount1Min,address recipient,uint256 deadline)) payable returns (uint256 tokenId,uint128 liquidity,uint256 amount0,uint256 amount1)',
  'function safeTransferFrom(address,address,uint256)',
];
const REACTOR_ABI = ['function addPool(uint256) external', 'function poolCount() view returns (uint256)'];
const FACTORY_ABI = ['function getPool(address,address,uint24) view returns (address)', 'function createPool(address,address,uint24) returns (address)'];
const POOL_ABI = ['function initialize(uint160 sqrtPriceX96)', 'function slot0() view returns (uint160,int24,uint16,uint16,uint16,uint8,bool)'];

function log(msg) { console.log('[' + new Date().toISOString().slice(0, 19) + '] ' + msg); }
function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function gas() {
  const fee = await p.getFeeData();
  return { maxFeePerGas: fee.maxFeePerGas * 2n, maxPriorityFeePerGas: fee.maxPriorityFeePerGas * 2n };
}

function calcSqrtPriceX96(usd0, dec0, usd1, dec1) {
  const priceFloat = (usd0 / usd1) * Math.pow(10, dec1 - dec0);
  const sqrtPrice = Math.sqrt(priceFloat);
  const Q96 = 2n ** 96n;
  const scaled = BigInt(Math.round(sqrtPrice * 1e18));
  return (scaled * Q96) / BigInt(1e18);
}

async function ensurePoolReady(factory, pairAddr, pairDec, pairUsd) {
  const ZERO = '0x0000000000000000000000000000000000000000';
  let poolAddr = await factory.getPool(NATION, pairAddr, FEE);

  if (poolAddr === ZERO) {
    log('  Creating V3 1% pool...');
    const tx = await factory.createPool(NATION, pairAddr, FEE, await gas());
    await tx.wait();
    poolAddr = await factory.getPool(NATION, pairAddr, FEE);
    log('  Pool: ' + poolAddr);
  } else {
    log('  Pool exists: ' + poolAddr);
  }

  if (poolAddr === ZERO) throw new Error('Pool creation failed');

  const pool = new ethers.Contract(poolAddr, POOL_ABI, wallet);
  try {
    const slot0 = await pool.slot0();
    if (slot0[0] === 0n) {
      const nIsT0 = NATION.toLowerCase() < pairAddr.toLowerCase();
      const usd0 = nIsT0 ? NATION_USD : pairUsd;
      const dec0 = nIsT0 ? NATION_DEC : pairDec;
      const usd1 = nIsT0 ? pairUsd : NATION_USD;
      const dec1 = nIsT0 ? pairDec : NATION_DEC;
      const sqrtPrice = calcSqrtPriceX96(usd0, dec0, usd1, dec1);
      log('  Initializing sqrtPriceX96: ' + sqrtPrice.toString());
      const tx = await pool.initialize(sqrtPrice, await gas());
      await tx.wait();
      log('  Initialized');
    } else {
      log('  Already initialized');
    }
  } catch (e) {
    const nIsT0 = NATION.toLowerCase() < pairAddr.toLowerCase();
    const usd0 = nIsT0 ? NATION_USD : pairUsd;
    const dec0 = nIsT0 ? NATION_DEC : pairDec;
    const usd1 = nIsT0 ? pairUsd : NATION_USD;
    const dec1 = nIsT0 ? pairDec : NATION_DEC;
    const sqrtPrice = calcSqrtPriceX96(usd0, dec0, usd1, dec1);
    log('  Initializing sqrtPriceX96: ' + sqrtPrice.toString());
    const tx = await pool.initialize(sqrtPrice, await gas());
    await tx.wait();
    log('  Initialized');
  }
}

async function main() {
  const npm = new ethers.Contract(NPM, NPM_ABI, wallet);
  const factory = new ethers.Contract(V3_FACTORY, FACTORY_ABI, wallet);
  const nationC = new ethers.Contract(NATION, ERC20_ABI, wallet);

  log('Wallet: ' + wallet.address);
  const nationBal = await nationC.balanceOf(wallet.address);
  log(NATION_NAME + ' balance: ' + Number(ethers.formatUnits(nationBal, NATION_DEC)).toFixed(4));
  log('Pairs: ' + PAIRS.length);

  if (nationBal === 0n) { log('ERROR: No ' + NATION_NAME); process.exit(1); }

  // Phase 1: Deploy
  log('\n=== PHASE 1: DEPLOY ' + NATION_NAME + ' REACTOR ===');
  const f = new ethers.ContractFactory(DEPLOY_ABI, BYTECODE, wallet);
  const contract = await f.deploy(NATION, NPM, ROUTER, BURN_ADDRESS, await gas());
  await contract.waitForDeployment();
  const reactorAddr = await contract.getAddress();
  log(NATION_NAME + ' REACTOR: ' + reactorAddr);
  const reactor = new ethers.Contract(reactorAddr, REACTOR_ABI, wallet);

  // Phase 2: Approvals
  log('\n=== PHASE 2: APPROVALS ===');
  const nationAllow = await nationC.allowance(wallet.address, NPM);
  if (nationAllow < nationBal) {
    log('Approving ' + NATION_NAME + '...');
    const tx = await nationC.approve(NPM, ethers.MaxUint256, await gas());
    await tx.wait();
  }
  for (const pair of PAIRS) {
    const c = new ethers.Contract(pair.addr, ERC20_ABI, wallet);
    const bal = await c.balanceOf(wallet.address);
    if (bal === 0n) continue;
    const allow = await c.allowance(wallet.address, NPM);
    if (allow < bal) {
      log('Approving ' + pair.name + '...');
      const tx = await c.approve(NPM, ethers.MaxUint256, await gas());
      await tx.wait();
    }
  }
  log('Approvals done');

  // Phase 3: Mint
  log('\n=== PHASE 3: MINT POSITIONS ===');
  const nationPerPos = nationBal / BigInt(PAIRS.length);
  const nationPerPosUsd = Number(ethers.formatUnits(nationPerPos, NATION_DEC)) * NATION_USD;
  log('Per position: ' + Number(ethers.formatUnits(nationPerPos, NATION_DEC)).toFixed(4) + ' ' + NATION_NAME + ' ($' + nationPerPosUsd.toFixed(2) + ')');

  let minted = 0;
  const skipped = [];

  for (const pair of PAIRS) {
    log('\n  --- ' + NATION_NAME + '/' + pair.name + ' ---');

    const currentNation = await nationC.balanceOf(wallet.address);
    const nationUse = currentNation > nationPerPos ? nationPerPos : currentNation;
    if (nationUse <= 0n) { log('  SKIP — no ' + NATION_NAME); skipped.push(pair.name); continue; }

    const nationUsdVal = Number(ethers.formatUnits(nationUse, NATION_DEC)) * NATION_USD;
    const pairTokens = nationUsdVal / pair.usd;
    const pairAmount = ethers.parseUnits(Math.floor(pairTokens).toString(), pair.dec);

    const pairC = new ethers.Contract(pair.addr, ERC20_ABI, wallet);
    const pairBal = await pairC.balanceOf(wallet.address);
    if (pairBal === 0n) { log('  SKIP — zero ' + pair.name); skipped.push(pair.name); continue; }
    const pairUse = pairBal < pairAmount ? pairBal : pairAmount;

    log('  ' + NATION_NAME + ': ' + Number(ethers.formatUnits(nationUse, NATION_DEC)).toFixed(4) + ' ($' + nationUsdVal.toFixed(2) + ')');
    log('  ' + pair.name + ': ' + Number(ethers.formatUnits(pairUse, pair.dec)).toLocaleString() + ' ($' + (Number(ethers.formatUnits(pairUse, pair.dec)) * pair.usd).toFixed(2) + ')');

    try {
      await ensurePoolReady(factory, pair.addr, pair.dec, pair.usd);

      const nationLower = NATION.toLowerCase() < pair.addr.toLowerCase();
      const token0 = nationLower ? NATION : pair.addr;
      const token1 = nationLower ? pair.addr : NATION;
      const amount0 = nationLower ? nationUse : pairUse;
      const amount1 = nationLower ? pairUse : nationUse;

      const deadline = Math.floor(Date.now() / 1000) + 600;
      log('  Minting...');
      const tx = await npm.mint({
        token0, token1, fee: FEE,
        tickLower: TICK_LOW, tickUpper: TICK_HIGH,
        amount0Desired: amount0, amount1Desired: amount1,
        amount0Min: 0n, amount1Min: 0n,
        recipient: wallet.address, deadline,
      }, await gas());
      const receipt = await tx.wait();

      const transferTopic = ethers.id('Transfer(address,address,uint256)');
      const mintLog = receipt.logs.find(l =>
        l.address.toLowerCase() === NPM.toLowerCase() && l.topics[0] === transferTopic
      );
      const tokenId = BigInt(mintLog.topics[3]);
      log('  MINTED #' + tokenId.toString() + ' | gas=' + receipt.gasUsed.toString());

      log('  Transferring to reactor...');
      const tx2 = await npm.safeTransferFrom(wallet.address, reactorAddr, tokenId, await gas());
      await tx2.wait();
      log('  Transferred');

      log('  Adding pool...');
      const tx3 = await reactor.addPool(tokenId, await gas());
      await tx3.wait();
      const count = await reactor.poolCount();
      log('  addPool done — ' + NATION_NAME + ' reactor: ' + count.toString() + ' pools');
      minted++;

      if (PAIRS.indexOf(pair) < PAIRS.length - 1) {
        log('  Waiting 2 min...');
        await sleep(120000);
      }
    } catch (e) {
      log('  ERROR: ' + (e.shortMessage || e.message).slice(0, 200));
      skipped.push(pair.name + ' (error)');
    }
  }

  const nationLeft = await nationC.balanceOf(wallet.address);
  const finalCount = await reactor.poolCount();
  log('\n========================================');
  log(NATION_NAME + ' REACTOR: ' + reactorAddr);
  log('Pools: ' + finalCount.toString());
  log('Minted: ' + minted + '/' + PAIRS.length);
  log(NATION_NAME + ' remaining: ' + Number(ethers.formatUnits(nationLeft, NATION_DEC)).toFixed(4));
  if (skipped.length > 0) {
    log('\nSkipped:');
    skipped.forEach(s => log('  - ' + s));
  }
  log('\n>>> Add to reactor-keeper.js:');
  log("  { name: '" + NATION_NAME + "', addr: '" + reactorAddr + "', token: '" + NATION + "', dec: " + NATION_DEC + " },");
}

main().catch(e => { console.error('Fatal:', e.shortMessage || e.message); process.exit(1); });
